//! `vis optimize` — the native port of the report `src/commands/optimize/handler.ts` prints when no terminal
//! is attached: the `module-replacements` and `@socketregistry` entries that match the dependencies of the
//! workspace, as pail text or (`--format json`) as JSON.
//!
//! The replacement data is `optimize-tables.json`, generated by `src/commands/optimize/native-tables.ts` from the
//! functions the Node handler runs and guarded by `__tests__/native/optimize-tables.test.ts`, so a dependency
//! bump cannot change one side only. The binary answers only the context it can prove, like `clean` and
//! `sort-package-json`: CI, no terminal, a pnpm workspace (run from its root or from a directory below it, since the
//! report names no path and Node works from the root it finds), a `vis.config.*`
//! that is absent or a plain literal Node loads without a word ([`config_leaves_the_report_alone`]), and pail output
//! it can reproduce. It hands everything else to Node before printing anything:
//!
//! - every shape that is interactive or applies anything (a terminal, which is the TUI), and every flag outside
//!   `--dry-run`/`-d`, `--format table|json`, `--no-install`, `--pin` and `--prod`;
//! - a config that has to be evaluated, or that Node fails on or prints about while it loads it (`extends`, `runtime`,
//!   `versionConstraint`, a removed key, a task whose list fields `includes` cannot be called on);
//! - a package manager other than pnpm, a workspace pattern or `.gitignore` line outside the subsets of
//!   [`crate::workspace`], and a `package.json` that is not strict JSON (Node may read it differently);
//! - a character other than printable ASCII and the two symbols the report prints (`→`, `⚙`), which pail would
//!   measure in a way this crate does not reproduce (lines that need wrapping are wrapped like pail does it).
//!
//! Nothing is written, so a delegation never follows a change to a file.

use std::collections::BTreeSet;
use std::env;
use std::ffi::OsString;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::exit;

use serde::Deserialize;
use serde_json::Value;
use vis_core::detect::detect_package_manager;

use crate::js::{is_js_whitespace, PROTOTYPE_NAMES};
use crate::json::Json;
use crate::node_context::{ci_context, quiet_environment, workspace_root};
use crate::output::write_stdout;
use crate::pail::{Layout, Level};
use crate::root_search::{read_json, Manager};
use crate::vis_config::{self, ConfigState};
use crate::workspace::directories_of_workspace;

const TABLES_JSON: &str = include_str!("../optimize-tables.json");

/// `[category, package, replacement, hasCodemod]` and `[package, replacement, spec, pinnedSpec]` rows.
#[derive(Deserialize)]
struct Tables {
    e18e: Vec<(String, String, String, bool)>,
    socket: Vec<(String, String, String, String)>,
}

#[derive(Default)]
struct Options {
    dry_run: bool,
    json: bool,
    pin: bool,
    prod: bool,
}

/// One entry of the e18e part of the report.
struct E18e<'a> {
    category: &'a str,
    package: &'a str,
    replacement: &'a str,
    codemod: bool,
}

/// One entry of the Socket.dev part of the report.
struct Socket<'a> {
    package: &'a str,
    replacement: &'a str,
    spec: &'a str,
}

/// Answer `vis optimize` natively, or delegate to Node. `args` is the lossy view used for matching,
/// `raw_args` the untouched argv handed to Node. Never returns.
pub fn run(args: &[String], raw_args: &[OsString]) -> ! {
    let Some(options) = parse(args) else {
        crate::process::delegate(raw_args);
    };
    let Some((layout, root, manager)) = context(args) else {
        crate::process::delegate(raw_args);
    };
    let Some(tables) = serde_json::from_str::<Tables>(TABLES_JSON).ok() else {
        crate::process::delegate(raw_args);
    };
    let Some(output) = report(&options, layout, &root, manager, &tables) else {
        crate::process::delegate(raw_args);
    };

    write_stdout("optimize", "the output", &output);

    exit(0)
}

/// The flags this path understands, or `None` when the invocation needs Node. `args` is the full argv, so the
/// first word is `optimize`. Each flag may appear once; `--format` takes `table` or `json`, as `--format value`
/// or `--format=value`.
fn parse(args: &[String]) -> Option<Options> {
    let mut options = Options::default();
    let mut seen: Vec<&str> = Vec::new();
    let mut index = 1;

    // A lossy argv conversion turns invalid UTF-8 into U+FFFD. Node would see the raw bytes.
    if args.iter().any(|argument| argument.contains('\u{FFFD}')) {
        return None;
    }

    while index < args.len() {
        let token = args[index].as_str();
        let (name, inline) = match token.split_once('=') {
            Some((name, value)) if name == "--format" => (name, Some(value)),
            _ => (token, None),
        };

        let flag = match (name, inline) {
            ("--dry-run" | "-d", None) => {
                options.dry_run = true;
                "--dry-run"
            }
            ("--pin", None) => {
                options.pin = true;
                name
            }
            ("--prod", None) => {
                options.prod = true;
                name
            }
            ("--no-install", None) => name,
            ("--format", _) => {
                let value = match inline {
                    Some(value) => value,
                    None => {
                        index += 1;

                        args.get(index)?.as_str()
                    }
                };

                options.json = match value {
                    "json" => true,
                    "table" => false,
                    _ => return None,
                };
                name
            }
            _ => return None,
        };

        if seen.contains(&flag) {
            return None;
        }

        seen.push(flag);
        index += 1;
    }

    Some(options)
}

/// Whether Node would reach the same answer, and the layout pail prints in. `None` is a delegation.
fn context(args: &[String]) -> Option<(Layout, PathBuf, Manager)> {
    let layout = Layout::detect(args)?;
    let cwd = env::current_dir().ok()?;

    // Node works from the workspace root, which it finds from the working directory (the report names no path, so
    // a project directory prints the same as the root does); this crate finds that root for a pnpm, npm or yarn workspace.
    let (root, manager) = workspace_root(&cwd)?;

    if !ci_context(&root) || !quiet_environment(&cwd, &root) || !config_leaves_the_report_alone(&root) {
        return None;
    }

    Some((layout, root, manager))
}

/// The keys of a task that `mergeTargetWithInherit` calls `includes` on while the config loads.
const TASK_LIST_FIELDS: [&str; 4] = ["aliases", "dependsOn", "inputs", "outputs"];

/// Whether the `vis.config` of the workspace root `root`, if there is one, changes nothing that Node prints for this
/// command. The report reads no setting: only the load of the config can print (to stderr, in CI) or fail, and
/// `afterCommand` hooks that read it stay quiet in CI or run for other commands (`security` is read for the package-manager
/// commands only, which is why it is the one key allowed here that [`vis_config::requires_node`] would not).
///
/// That is a config that is a plain literal and is not one of the shapes the Node loader fails or prints on: a key only
/// Node handles (`extends`, `runtime`, `versionConstraint`, the removed keys, an `install` it must run), a `__proto__` key
/// (a literal sets the prototype with it, a map holds a key), or a task whose list fields `includes` cannot be called on.
/// A config in a parent directory, or in the root in a form Node does not evaluate, is never loaded. The file also has to be
/// one Node loads as the module it is written as ([`module_format_loads`]).
fn config_leaves_the_report_alone(root: &Path) -> bool {
    let config = match vis_config::read(root) {
        ConfigState::Absent => return true,
        ConfigState::Dynamic => return false,
        ConfigState::Static(config) => config,
    };

    // Node loads the script config of the workspace root only. A `.json` file is never loaded; a config above the
    // root is a case this module leaves to Node.
    let Some(file) = vis_config::config_file_in(root) else {
        return false;
    };

    let extension = file.extension().and_then(|extension| extension.to_str());

    if extension == Some("json") {
        return true;
    }

    if !module_format_loads(root, extension) {
        return false;
    }

    let mut rest = config.clone();

    if let Some(map) = rest.as_object_mut() {
        map.remove("security");
    }

    !vis_config::requires_node(&ConfigState::Static(rest)) && !holds_proto_key(&config) && tasks_load(&config)
}

/// Whether Node loads a config with this extension in the package scope of the root `package.json` without a word. A
/// `.cts` or `.cjs` file is CommonJS, which its `export default` is not; a `.js` file is CommonJS under `"type": "commonjs"`
/// (Node warns and the loader prints an error block); and a `type` that is not a string makes Node reject the manifest for
/// the `.ts` and `.js` files that read their package scope (`.mts` and `.mjs` never do). Probed against the Node CLI: a `.ts`
/// loads under any string `type`, a `.js` under none or `module`.
fn module_format_loads(root: &Path, extension: Option<&str>) -> bool {
    match extension {
        Some("cts" | "cjs") => false,
        Some(extension @ ("ts" | "js")) => {
            let manifest = root.join("package.json");

            if !manifest.exists() {
                return true;
            }

            let Some(manifest) = read_json(&manifest) else {
                return false;
            };

            match manifest.get("type") {
                None => true,
                Some(Value::String(module_type)) => extension == "ts" || module_type == "module",
                Some(_) => false,
            }
        }
        _ => true,
    }
}

/// Whether `value` holds an object key named `__proto__` anywhere.
fn holds_proto_key(value: &Value) -> bool {
    match value {
        Value::Object(map) => map.contains_key("__proto__") || map.values().any(holds_proto_key),
        Value::Array(items) => items.iter().any(holds_proto_key),
        _ => false,
    }
}

/// Whether the `tasks` of a config merge without an error: `mergeTargetWithInherit` calls `includes` on the list fields of
/// each task, which throws for a `null`, a number, a boolean or an object (an array and a string have it).
fn tasks_load(config: &Value) -> bool {
    match config.get("tasks") {
        None | Some(Value::Null) => true,
        Some(Value::Object(tasks)) if PROTOTYPE_NAMES.iter().any(|name| tasks.contains_key(*name)) => false,
        Some(Value::Object(tasks)) => tasks.values().all(|task| match task {
            Value::Object(task) => TASK_LIST_FIELDS
                .iter()
                .all(|field| matches!(task.get(*field), None | Some(Value::Array(_) | Value::String(_)))),
            _ => true,
        }),
        // Any other value is read as a map of tasks by the loader, in a way this module does not reproduce.
        Some(_) => false,
    }
}

/// The text of the whole run, or `None` when something on the way is outside what this module reproduces.
fn report(options: &Options, layout: Layout, root: &Path, manager: Manager, tables: &Tables) -> Option<String> {
    let detected = detect_package_manager(root.to_str()?, None);

    // Everything below follows the manager the handler detects (`detectPm`): its name, the lockfile it reads and how it
    // searches it. A root whose lockfile names one manager and a pin or config file another is Node's.
    if detected.name != manager.name() {
        return None;
    }

    let manager = manager.name();

    // `detected.version || "latest"`.
    let version = detected.version.filter(|version| !version.is_empty()).unwrap_or_else(|| "latest".to_owned());
    let directories = directories_of_workspace(root)?;

    let mut dependencies = read_dependencies(&root.join("package.json"), options.prod)?;

    for directory in &directories {
        dependencies.extend(read_dependencies(&root.join(directory).join("package.json"), options.prod)?);
    }

    let mut out = String::new();
    let mut say = |level: Level, message: &str| -> Option<()> {
        out.push_str(&layout.block_fitting(level, message)?);

        Some(())
    };

    say(Level::Info, &format!("Detected {manager} v{version}."))?;

    if !directories.is_empty() {
        let count = directories.len();

        say(Level::Info, &format!("Scanned {count} workspace package{}.", if count == 1 { "" } else { "s" }))?;
    }

    say(Level::Info, "Scanning dependencies...\n")?;

    let lockfile = lockfile_text(root, manager);
    let e18e: Vec<E18e> = tables
        .e18e
        .iter()
        .filter(|(_, package, ..)| dependencies.contains(package))
        .map(|(category, package, replacement, codemod)| E18e { category, package, replacement, codemod: *codemod })
        .collect();
    // An e18e entry wins over an override of the same package.
    let socket: Vec<Socket> = tables
        .socket
        .iter()
        .filter(|(package, ..)| dependencies.contains(package) || lockfile_contains(manager, &lockfile, package))
        .filter(|(package, ..)| !e18e.iter().any(|entry| entry.package == package))
        .map(|(package, replacement, spec, pinned)| Socket {
            package,
            replacement,
            spec: if options.pin { pinned } else { spec },
        })
        .collect();
    let total = e18e.len() + socket.len();

    if total == 0 {
        say(Level::Info, "No optimizations found for your dependencies.")?;

        return Some(out);
    }

    if options.json {
        out.push_str(&json_report(manager, &e18e, &socket, total, directories.len()));

        return Some(out);
    }

    for (category, title, lead) in [
        ("native", "Native replacements", ""),
        ("preferred", "Preferred alternatives", "\n"),
        ("micro-utility", "Micro-utilities", "\n"),
    ] {
        let entries: Vec<&E18e> = e18e.iter().filter(|entry| entry.category == category).collect();

        if entries.is_empty() {
            continue;
        }

        say(Level::Info, &format!("{lead}{title} ({}):", entries.len()))?;

        for entry in entries {
            say(
                Level::Info,
                &format!(
                    "  {} {} \u{2192} {}",
                    if entry.codemod { "\u{2699}" } else { " " },
                    entry.package,
                    entry.replacement
                ),
            )?;
        }
    }

    if !socket.is_empty() {
        say(Level::Info, &format!("\nSocket.dev overrides ({}):", socket.len()))?;

        for entry in &socket {
            say(Level::Info, &format!("  {} \u{2192} {}", entry.package, entry.spec))?;
        }
    }

    say(Level::Info, &format!("\nTotal: {total} optimizations available (\u{2699} = codemod available)."))?;

    if options.dry_run {
        say(Level::Notice, "Run without --dry-run for interactive selection.")?;
    }

    Some(out)
}

/// `JSON.stringify(report, undefined, 2)` and a newline. The keys are in the order the handler builds them.
fn json_report(manager: &str, e18e: &[E18e], socket: &[Socket], total: usize, workspaces: usize) -> String {
    let text = |value: &str| Json::Str(value.to_owned());
    let number = |value: usize| Json::Int(i64::try_from(value).unwrap_or(i64::MAX));
    let report = Json::Object(vec![
        (
            "e18e".to_owned(),
            Json::Array(
                e18e.iter()
                    .map(|entry| {
                        Json::Object(vec![
                            ("category".to_owned(), text(entry.category)),
                            ("hasCodemod".to_owned(), Json::Bool(entry.codemod)),
                            ("packageName".to_owned(), text(entry.package)),
                            ("replacement".to_owned(), text(entry.replacement)),
                        ])
                    })
                    .collect(),
            ),
        ),
        ("packageManager".to_owned(), text(manager)),
        (
            "socket".to_owned(),
            Json::Array(
                socket
                    .iter()
                    .map(|entry| {
                        Json::Object(vec![
                            ("overrideSpec".to_owned(), text(entry.spec)),
                            ("packageName".to_owned(), text(entry.package)),
                            ("replacement".to_owned(), text(entry.replacement)),
                        ])
                    })
                    .collect(),
            ),
        ),
        ("total".to_owned(), number(total)),
        ("workspaces".to_owned(), number(workspaces)),
    ]);

    format!("{}\n", crate::json::stringify(&report, "  "))
}

/// `collectDepsFromPkgJson`: the dependency names of one manifest. A file that cannot be read gives none, as the
/// handler's `catch` does; a file that is not strict JSON, or a dependency map JavaScript would read in a way
/// this crate does not reproduce, is `None`.
fn read_dependencies(manifest: &Path, production_only: bool) -> Option<BTreeSet<String>> {
    let mut names = BTreeSet::new();

    let Ok(bytes) = fs::read(manifest) else {
        return Some(names);
    };

    let manifest: Value = serde_json::from_str(std::str::from_utf8(&bytes).ok()?).ok()?;
    let keys: &[&str] = if production_only {
        &["dependencies", "optionalDependencies"]
    } else {
        &["dependencies", "devDependencies", "peerDependencies", "optionalDependencies"]
    };

    for key in keys {
        match manifest.get(*key) {
            None | Some(Value::Null | Value::Bool(false)) => {}
            Some(Value::Object(map)) => {
                names.extend(map.keys().cloned());
            }
            // A string, a number or an array: `Object.keys` lists indices or characters.
            Some(value) if is_falsy(value) => {}
            Some(_) => return None,
        }
    }

    Some(names)
}

/// JavaScript falsiness of a JSON value other than `null` and `false`: `0` and the empty string.
fn is_falsy(value: &Value) -> bool {
    match value {
        Value::Number(number) => number.as_f64().is_some_and(|number| number == 0.0),
        Value::String(text) => text.is_empty(),
        _ => false,
    }
}

/// `readLockfileText`: the first lockfile of the manager that can be read, an empty one included (an empty
/// `npm-shrinkwrap.json` hides a `package-lock.json`), decoded the way Node decodes a file (invalid bytes become U+FFFD).
fn lockfile_text(root: &Path, manager: &str) -> String {
    let names: &[&str] = match manager {
        "npm" => &["npm-shrinkwrap.json", "package-lock.json"],
        "yarn" => &["yarn.lock"],
        _ => &["pnpm-lock.yaml"],
    };

    names
        .iter()
        .find_map(|name| fs::read(root.join(name)).ok())
        .map_or_else(String::new, |bytes| String::from_utf8_lossy(&bytes).into_owned())
}

/// `lockfileContainsPackage`: whether the lockfile text names `package`, searched the way the handler does for each manager
/// (`overrides.ts`):
///
/// - npm: `"<name>":` or `"node_modules/<name>":` anywhere;
/// - yarn: `/(^|\s|[",])<name>@/m`;
/// - pnpm: `/(^|\s|['"/])<name>(@|['"]?:)/m`.
///
/// `package` is matched as plain text, which is what the handler's escaping of the name makes of it.
fn lockfile_contains(manager: &str, text: &str, package: &str) -> bool {
    if text.is_empty() {
        return false;
    }

    match manager {
        "npm" => text.contains(&format!("\"{package}\":")) || text.contains(&format!("\"node_modules/{package}\":")),
        "yarn" => follows_boundary(text, package, |character| matches!(character, '"' | ','), |rest| rest.starts_with('@')),
        _ => follows_boundary(
            text,
            package,
            |character| matches!(character, '\'' | '"' | '/'),
            |rest| rest.starts_with('@') || rest.strip_prefix(['\'', '"']).unwrap_or(rest).starts_with(':'),
        ),
    }
}

/// Whether `text` holds `package` after the start of a line, a whitespace character (`^` and `\s` of the patterns) or a
/// character `boundary` accepts, and before a rest that `follows` accepts. Occurrences may overlap.
fn follows_boundary(text: &str, package: &str, boundary: impl Fn(char) -> bool, follows: impl Fn(&str) -> bool) -> bool {
    let mut from = 0;

    while let Some(offset) = text[from..].find(package) {
        let start = from + offset;
        let before = text[..start].chars().next_back();

        if before.is_none_or(|character| is_js_whitespace(character) || boundary(character)) && follows(&text[start + package.len()..]) {
            return true;
        }

        from = start + text[start..].chars().next().map_or(1, char::len_utf8);
    }

    false
}

#[cfg(test)]
mod tests {
    use super::*;

    fn args(words: &[&str]) -> Vec<String> {
        std::iter::once("optimize").chain(words.iter().copied()).map(str::to_owned).collect()
    }

    #[test]
    fn the_shipped_tables_parse() {
        let tables: Tables = serde_json::from_str(TABLES_JSON).unwrap();

        assert!(!tables.socket.is_empty());
    }

    #[test]
    fn flags_are_taken_once_and_only_known_ones() {
        assert!(parse(&args(&[])).is_some());
        assert!(parse(&args(&["--dry-run", "--pin", "--prod", "--no-install", "--format", "json"])).is_some());
        assert!(parse(&args(&["-d", "--format=table"])).is_some());
        assert!(parse(&args(&["--dry-run", "-d"])).is_none());
        assert!(parse(&args(&["--format", "xml"])).is_none());
        assert!(parse(&args(&["--format"])).is_none());
        assert!(parse(&args(&["--json"])).is_none());
        assert!(parse(&args(&["pkg"])).is_none());
    }

    #[test]
    fn the_lockfile_match_follows_the_pnpm_pattern() {
        let text = "packages:\n  /abab@1.0.0:\n    resolution: x\n  'left-pad':\n  other: left-pad@1\nx.abab:\n";

        assert!(lockfile_contains("pnpm", text, "abab"));
        assert!(lockfile_contains("pnpm", text, "left-pad"));
        assert!(!lockfile_contains("pnpm", text, "ab"));
        assert!(!lockfile_contains("pnpm", text, "pad"));
        assert!(!lockfile_contains("pnpm", "", "abab"));
        assert!(lockfile_contains("pnpm", "abab: 1", "abab"));
        assert!(lockfile_contains("pnpm", "\u{a0}abab@1", "abab"));
        assert!(!lockfile_contains("pnpm", "xabab@1", "abab"));
        // An occurrence that overlaps the one before it is still found.
        assert!(lockfile_contains("pnpm", "a/a/a@1", "a/a"));
    }

    #[test]
    fn the_lockfile_match_follows_the_yarn_and_npm_patterns() {
        let yarn = "# yarn lockfile v1\n\nabab@^1.0.0, \"left-pad@^1\":\n  version \"1.0.0\"\nx.other@1:\n";

        assert!(lockfile_contains("yarn", yarn, "abab"));
        assert!(lockfile_contains("yarn", yarn, "left-pad"));
        assert!(lockfile_contains("yarn", "\"abab@npm:^1\":", "abab"));
        assert!(lockfile_contains("yarn", "a,abab@1", "abab"));
        assert!(!lockfile_contains("yarn", yarn, "other"));
        // `/` and `'` bound a pnpm key only.
        assert!(!lockfile_contains("yarn", "/abab@1", "abab"));
        assert!(!lockfile_contains("yarn", "abab: 1", "abab"));
        assert!(!lockfile_contains("yarn", "", "abab"));

        let npm = "{\n \"packages\": {\n  \"node_modules/abab\": {},\n  \"left-pad\": \"1\"\n }\n}\n";

        assert!(lockfile_contains("npm", npm, "abab"));
        assert!(lockfile_contains("npm", npm, "left-pad"));
        assert!(!lockfile_contains("npm", npm, "pad"));
        assert!(!lockfile_contains("npm", "abab@1\n", "abab"));
        assert!(!lockfile_contains("npm", "{\"abab\" : 1}", "abab"));
    }

    #[test]
    fn the_first_readable_lockfile_of_the_manager_is_read_even_when_it_is_empty() {
        let dir = workspace("lockfiles", &[]);

        fs::write(dir.join("package-lock.json"), "{\"abab\": 1}").unwrap();
        fs::write(dir.join("yarn.lock"), "abab@1:\n").unwrap();

        assert_eq!(lockfile_text(&dir, "npm"), "{\"abab\": 1}");
        assert_eq!(lockfile_text(&dir, "yarn"), "abab@1:\n");
        assert_eq!(lockfile_text(&dir, "pnpm"), "lockfileVersion: 9\n");

        fs::write(dir.join("npm-shrinkwrap.json"), "").unwrap();

        assert_eq!(lockfile_text(&dir, "npm"), "");

        // A directory of that name cannot be read, so the next name is tried.
        fs::remove_file(dir.join("npm-shrinkwrap.json")).unwrap();
        fs::create_dir(dir.join("npm-shrinkwrap.json")).unwrap();

        assert_eq!(lockfile_text(&dir, "npm"), "{\"abab\": 1}");

        let _ = fs::remove_dir_all(&dir);
    }

    #[test]
    fn dependency_maps_follow_object_keys() {
        let dir = std::env::temp_dir().join(format!("vis-optimize-{}", std::process::id()));

        fs::create_dir_all(&dir).unwrap();

        let path = dir.join("package.json");

        fs::write(&path, r#"{"dependencies":{"a":"1"},"devDependencies":{"b":"1"},"peerDependencies":null,"optionalDependencies":{}}"#).unwrap();

        assert_eq!(read_dependencies(&path, false).unwrap().into_iter().collect::<Vec<_>>(), ["a", "b"]);
        assert_eq!(read_dependencies(&path, true).unwrap().into_iter().collect::<Vec<_>>(), ["a"]);

        fs::write(&path, r#"{"dependencies":"abc"}"#).unwrap();

        assert!(read_dependencies(&path, false).is_none());

        fs::write(&path, r#"{"dependencies":0, "devDependencies": []}"#).unwrap();

        assert!(read_dependencies(&path, false).is_none());

        fs::write(&path, "{ not json").unwrap();

        assert!(read_dependencies(&path, false).is_none());
        assert!(read_dependencies(&dir.join("missing.json"), false).unwrap().is_empty());

        let _ = fs::remove_dir_all(&dir);
    }

    /// Whether the config rule accepts a root holding `files` (name and content).
    fn accepts(name: &str, files: &[(&str, &str)]) -> bool {
        let dir = std::env::temp_dir().join(format!("vis-optimize-config-{}-{name}", std::process::id()));

        let _ = fs::remove_dir_all(&dir);
        fs::create_dir_all(&dir).unwrap();

        for (file, content) in files {
            fs::write(dir.join(file), content).unwrap();
        }

        let accepted = config_leaves_the_report_alone(&dir);

        let _ = fs::remove_dir_all(&dir);

        accepted
    }

    #[test]
    fn a_literal_config_that_loads_quietly_is_accepted() {
        assert!(accepts("none", &[]));
        assert!(accepts("empty", &[("vis.config.ts", "export default {};\n")]));
        assert!(accepts("mjs", &[("vis.config.mjs", "export default { cache: { enabled: true } };\n")]));
        assert!(accepts("unknown", &[("vis.config.ts", "export default { nope: 1, update: 5, plugins: [{ name: 'x' }] };\n")]));
        assert!(accepts("backend", &[("vis.config.ts", "export default { install: { backend: 'npm' } };\n")]));
        // `security` is read for the package-manager commands only.
        assert!(accepts("security", &[("vis.config.ts", "export default { security: { allowBuilds: { esbuild: true } } };\n")]));
        assert!(accepts(
            "tasks",
            &[("vis.config.ts", "export default { tasks: { build: { inputs: ['a'], dependsOn: '^build', outputs: ['@inherit'] }, empty: null } };\n")]
        ));
        // Node never loads a `.json` config.
        assert!(accepts("json", &[("vis.config.json", "{\"runtime\":\"bun\"}")]));
    }

    #[test]
    fn a_config_that_node_evaluates_fails_on_or_prints_about_is_declined() {
        for (name, source) in [
            ("call", "export default makeConfig();\n"),
            ("extends", "export default { extends: './base.ts' };\n"),
            ("runtime", "export default { runtime: 'bun' };\n"),
            ("constraint", "export default { versionConstraint: '>=1' };\n"),
            ("removed", "export default { targetDefaults: {} };\n"),
            ("scoped", "export default { scopedTasks: [] };\n"),
            ("corepack", "export default { install: { corepack: true } };\n"),
            ("backend", "export default { install: { backend: 'yarn' } };\n"),
            ("proto", "export default { update: { \"__proto__\": { a: 1 } } };\n"),
            ("input-number", "export default { tasks: { build: { inputs: 5 } } };\n"),
            ("input-null", "export default { tasks: { build: { dependsOn: null } } };\n"),
            ("input-object", "export default { tasks: { build: { outputs: {} } } };\n"),
            ("tasks-string", "export default { tasks: 'abc' };\n"),
            ("duplicate", "export default { cache: 1, cache: 2 };\n"),
            ("unwrapped", "import { defineConfig } from '@visulima/vis/config';\nexport default defineConfig({});\n"),
        ] {
            assert!(!accepts(name, &[("vis.config.ts", source)]), "{name}");
        }

        // A script config of a form Node cannot load as ESM prints an error block.
        assert!(!accepts("cjs", &[("vis.config.cjs", "export default {};\n")]));
        assert!(!accepts("cts", &[("vis.config.cts", "export default {};\n")]));
        // A config that is not valid JSON is not read as data either.
        assert!(!accepts("bad-json", &[("vis.config.json", "{ not json")]));
    }

    #[test]
    fn the_package_scope_of_the_root_decides_which_script_configs_load() {
        let config = "export default { cache: {} };\n";

        for (name, file, manifest, accepted) in [
            ("ts-none", "vis.config.ts", r#"{"name":"r"}"#, true),
            ("ts-commonjs", "vis.config.ts", r#"{"type":"commonjs"}"#, true),
            ("ts-module", "vis.config.ts", r#"{"type":"module"}"#, true),
            ("ts-other", "vis.config.ts", r#"{"type":"bogus"}"#, true),
            ("ts-number", "vis.config.ts", r#"{"type":1}"#, false),
            ("ts-null", "vis.config.ts", r#"{"type":null}"#, false),
            ("ts-array", "vis.config.ts", r#"{"type":["module"]}"#, false),
            ("js-none", "vis.config.js", r#"{"name":"r"}"#, true),
            ("js-module", "vis.config.js", r#"{"type":"module"}"#, true),
            ("js-commonjs", "vis.config.js", r#"{"type":"commonjs"}"#, false),
            ("js-other", "vis.config.js", r#"{"type":"bogus"}"#, false),
            ("js-null", "vis.config.js", r#"{"type":null}"#, false),
            ("mts-commonjs", "vis.config.mts", r#"{"type":"commonjs"}"#, true),
            ("mts-number", "vis.config.mts", r#"{"type":1}"#, true),
            ("mjs-commonjs", "vis.config.mjs", r#"{"type":"commonjs"}"#, true),
            ("ts-not-json", "vis.config.ts", "{ not json", false),
        ] {
            assert_eq!(accepts(name, &[(file, config), ("package.json", manifest)]), accepted, "{name}");
        }

        // No manifest at all leaves the scope without a `type`.
        assert!(accepts("no-manifest", &[("vis.config.js", config)]));
    }

    #[test]
    fn a_config_above_the_root_is_declined() {
        let dir = std::env::temp_dir().join(format!("vis-optimize-config-{}-above", std::process::id()));
        let root = dir.join("inner");

        let _ = fs::remove_dir_all(&dir);
        fs::create_dir_all(&root).unwrap();
        fs::write(dir.join("vis.config.ts"), "export default {};\n").unwrap();

        let accepted = config_leaves_the_report_alone(&root);

        let _ = fs::remove_dir_all(&dir);

        assert!(!accepted);
    }

    /// A pnpm workspace in a scratch directory with `dependencies` in its root manifest.
    fn workspace(name: &str, dependencies: &[&str]) -> PathBuf {
        let dir = std::env::temp_dir().join(format!("vis-optimize-report-{}-{name}", std::process::id()));
        let manifest = serde_json::json!({ "name": "root", "dependencies": dependencies.iter().map(|name| ((*name).to_owned(), Value::from("1"))).collect::<serde_json::Map<String, Value>>() });

        let _ = fs::remove_dir_all(&dir);
        fs::create_dir_all(&dir).unwrap();
        fs::write(dir.join("package.json"), manifest.to_string()).unwrap();
        fs::write(dir.join("pnpm-lock.yaml"), "lockfileVersion: 9\n").unwrap();
        fs::write(dir.join("pnpm-workspace.yaml"), "packages:\n  - \"packages/*\"\n").unwrap();

        dir
    }

    /// The e18e lists are empty with the shipped manifests, so the branches that print them run on a synthetic table.
    fn synthetic() -> Tables {
        let row = |category: &str, package: &str, replacement: &str, codemod: bool| {
            (category.to_owned(), package.to_owned(), replacement.to_owned(), codemod)
        };

        Tables {
            e18e: vec![
                row("native", "left-pad", "String.prototype.padStart (Node 8+)", true),
                row("preferred", "chalk", "see migration guide", false),
                row("micro-utility", "is-number", "", false),
                row("native", "not-used", "x", false),
            ],
            socket: vec![
                (
                    "chalk".to_owned(),
                    "@socketregistry/chalk".to_owned(),
                    "npm:@socketregistry/chalk@^1".to_owned(),
                    "npm:@socketregistry/chalk@1.0.0".to_owned(),
                ),
                (
                    "abab".to_owned(),
                    "@socketregistry/abab".to_owned(),
                    "npm:@socketregistry/abab@^1".to_owned(),
                    "npm:@socketregistry/abab@1.0.9".to_owned(),
                ),
            ],
        }
    }

    #[test]
    fn e18e_entries_print_by_category_and_win_over_an_override() {
        let dir = workspace("text", &["left-pad", "chalk", "is-number", "abab"]);
        let layout = Layout { width: 100, colour: false };
        let text = report(&Options::default(), layout, &dir, Manager::Pnpm, &synthetic()).unwrap();
        let _ = fs::remove_dir_all(&dir);
        let body: Vec<&str> = text.lines().filter(|line| !line.is_empty() && !line.contains(" INFO ...")).collect();

        assert_eq!(
            body,
            [
                "Detected pnpm vlatest.",
                "Scanning dependencies...",
                "Native replacements (1):",
                "  \u{2699} left-pad \u{2192} String.prototype.padStart (Node 8+)",
                "Preferred alternatives (1):",
                "    chalk \u{2192} see migration guide",
                "Micro-utilities (1):",
                "    is-number \u{2192} ",
                "Socket.dev overrides (1):",
                "  abab \u{2192} npm:@socketregistry/abab@^1",
                "Total: 4 optimizations available (\u{2699} = codemod available).",
            ]
        );
    }

    #[test]
    fn e18e_entries_are_in_the_json_with_their_codemod_flag() {
        let dir = workspace("json", &["left-pad", "chalk"]);
        let layout = Layout { width: 100, colour: false };
        let options = Options { json: true, ..Options::default() };
        let text = report(&options, layout, &dir, Manager::Pnpm, &synthetic()).unwrap();
        let _ = fs::remove_dir_all(&dir);
        let report: Value = serde_json::from_str(&text[text.find('{').unwrap()..]).unwrap();

        assert_eq!(
            report,
            serde_json::json!({
                "e18e": [
                    { "category": "native", "hasCodemod": true, "packageName": "left-pad", "replacement": "String.prototype.padStart (Node 8+)" },
                    { "category": "preferred", "hasCodemod": false, "packageName": "chalk", "replacement": "see migration guide" },
                ],
                "packageManager": "pnpm",
                "socket": [],
                "total": 2,
                "workspaces": 0,
            })
        );
    }
}
